  padding-top: 4px;
  border-top: 1px solid var(--line);
}

.toolbar[data-layout="Palette"] .level-chip {
  width: 44px;
  min-width: 0;
  padding: 0;
  font-size: 14px;
}

.toolbar[data-layout="Palette"] .level-list {
  top: 0;
  right: auto;
  left: calc(100% + 10px);
}

.toolbar[data-layout="Palette"] .level-list[data-side="Above"] {
  top: auto;
  bottom: 0;
}

