  }
}

.swatch.picker {
  overflow: hidden;
}

.swatch.picker .swatch-fill {
  background-image: conic-gradient(#e5484d, #f76b15, #30a46c, #0090ff, #8e4ec6, #e5484d);
}

.swatch.picker input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  cursor: pointer;
}

.hex-field {
  box-sizing: border-box;
  width: 100%;
  height: 36px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--panel);
  color: var(--ink);
  font:
    14px / 1 ui-monospace,
    monospace;
}

.hex-field[aria-invalid="true"] {
  border-color: #e5484d;
}

.toolbar[data-layout="Palette"] .hex-field {
  grid-column: 1 / -1;
}

.width-preset {
  color: var(--ink);
  font:
    600 13px / 1 system-ui,
    sans-serif;
}

.width-slider {
  box-sizing: border-box;
  width: 100%;
  height: 36px;
  margin: 0;
  accent-color: var(--ink);
}

.width-value {
  color: var(--ink);
  font:
    13px / 1 ui-monospace,
    monospace;
}

.toolbar[data-layout="Palette"] .width-slider,
.toolbar[data-layout="Palette"] .width-value {
  grid-column: 1 / -1;
}

.sticky-editor {
  position: fixed;
  z-index: 5;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 8px;
}

.sticky-editor.idle {
  left: 0;
  top: 0;
  width: 1px;
  height: 1px;
  overflow: hidden;
  opacity: 0;
  pointer-events: none;
}

.sticky-text {
  display: block;
  width: 100%;
  box-sizing: border-box;
  margin: 0;
  border: 0;
  border-radius: 0;
  outline: 2px solid var(--accent);
  outline-offset: 0;
  resize: none;
  overflow: hidden;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  user-select: text;
  -webkit-user-select: text;
  touch-action: manipulation;
}

.sticky-done {
  min-width: 64px;
  min-height: 44px;
  padding: 0 16px;
  border: 1px solid var(--line);
  border-radius: 22px;
  background: var(--panel);
  color: var(--ink);
  font:
    600 16px system-ui,
    sans-serif;
  box-shadow: 0 2px 8px #0000001f;
}

@media (max-width: 1279px) {
  .toolbar[data-layout="Wide"] .toolbar-row {
    gap: 2px;
  }

  .toolbar[data-layout="Wide"] .tool {
    width: 32px;
    height: 32px;
  }

  .toolbar[data-layout="Wide"] .swatch-fill {
    width: 24px;
    height: 24px;
  }

  .toolbar[data-layout="Wide"] .level-chip {
    min-width: 36px;
    height: 32px;
    padding: 0 8px;
  }
}
