import type { RefObject } from "preact";
import { useLayoutEffect } from "preact/hooks";

export const MIN_COLUMNS = 2;
export const PALETTE_GUTTER = 16;
export const NOTICE_GAP = 8;
const COLUMN_PITCH = 48;
const PALETTE_CHROME = 14;

export const maxColumns = (viewportWidth: number): number =>
  Math.max(
    MIN_COLUMNS,
    Math.floor((viewportWidth - 2 * PALETTE_GUTTER - PALETTE_CHROME + 4) / COLUMN_PITCH),
  );

export const paletteRoom = (
  viewportHeight: number,
  top: number,
  noticeTops: readonly number[],
): number => Math.min(viewportHeight - PALETTE_GUTTER, ...noticeTops.map((t) => t - NOTICE_GAP)) - top;

export const fitColumns = (
  heightAt: (columns: number) => number,
  room: number,
  most: number,
): number => {
  for (let columns = MIN_COLUMNS; columns < most; columns++) {
    if (heightAt(columns) <= room) return columns;
  }
  return most;
};

const noticeTops = (): number[] =>
  [...document.querySelectorAll(".notice")]
    .map((notice) => notice.getBoundingClientRect())
    .filter((rect) => rect.height > 0)
    .map((rect) => rect.top);

export const usePaletteFit = (ref: RefObject<HTMLElement>, active: boolean): void => {
  useLayoutEffect(() => {
    const bar = ref.current;
    if (!bar || !active) return;
    let notices = "";
    const fit = () => {
      const tops = noticeTops();
      notices = tops.join();
      const room = paletteRoom(window.innerHeight, bar.getBoundingClientRect().top, tops);
      const columns = fitColumns(
        (count) => {
          bar.style.setProperty("--palette-columns", String(count));
          return bar.offsetHeight;
        },
        room,
        maxColumns(window.innerWidth),
      );
      bar.style.setProperty("--palette-columns", String(columns));
    };
    const noticesChanged = () => {
      if (noticeTops().join() !== notices) fit();
    };
    fit();
    const resize = new ResizeObserver(fit);
    resize.observe(bar);
    const mutations = new MutationObserver(noticesChanged);
    mutations.observe(document.body, { childList: true, subtree: true });
    window.addEventListener("resize", fit);
    return () => {
      resize.disconnect();
      mutations.disconnect();
      window.removeEventListener("resize", fit);
      bar.style.removeProperty("--palette-columns");
    };
  }, [ref, active]);
};
EOF
cat > palette-fit.test.ts <<'EOF'
import { expect, test } from "vitest";
import { fitColumns, maxColumns, paletteRoom } from "./palette-fit";

const PALETTE_HEIGHTS: Record<number, number> = { 2: 1180, 3: 876, 4: 828, 5: 700, 6: 620 };
const heightAt = (columns: number) => PALETTE_HEIGHTS[columns] ?? 600;

test("adds columns until the palette fits a laptop viewport", () => {
  expect(fitColumns(heightAt, paletteRoom(789, 12, []), 12)).toBe(5);
  expect(fitColumns(heightAt, paletteRoom(823, 12, []), 12)).toBe(5);
  expect(fitColumns(heightAt, paletteRoom(1000, 12, []), 12)).toBe(3);
});

test("keeps two columns when the viewport is tall enough", () => {
  expect(fitColumns(heightAt, paletteRoom(1400, 12, []), 12)).toBe(2);
});

test("stops above a visible notice", () => {
  expect(paletteRoom(1000, 12, [920])).toBe(900);
  expect(fitColumns(heightAt, paletteRoom(1000, 12, [880]), 12)).toBe(4);
});

test("never grows wider than the viewport allows", () => {
  expect(maxColumns(412)).toBe(7);
  expect(fitColumns(() => 5000, 100, maxColumns(412))).toBe(7);
  expect(maxColumns(100)).toBe(2);
});
EOF
